B.Fu=new A.bk([B.X,"Este site foi desenvolvido por Edoardo Fabrizio De Iovanna, usando Flutter",B.a_,"Questo sito \xe8 stato sviluppato da Edoardo Fabrizio De Iovanna, usando Flutter",B.a0,"This site was developed by Edoardo Fabrizio De Iovanna, using Flutter"],t.Y)
B.Fv=new A.bk([B.X,"Hobbies e Interesses",B.a_,"Hobby e Interessi",B.a0,"Hobbies & Interests"],t.Y)
